  "supportive_card_ids": ["C269","C241","C197","C191","C184","C211","C181","C206","C207","C208","C213","C182","C205","C199","C212","C220","C85","C108","C95","C143","C153","C161","C162","C135","C146","C170","C151"],
  "contradictory_card_ids": ["C164"],
  "prediction_basis_card_ids": ["C269","C241","C197","C191","C184","C211","C181","C206","C207","C208","C213","C182","C205","C199","C212","C220","C85","C108","C95","C143","C153","C161","C162","C135","C146","C170","C151"],
  "claims": [
    {
      "claim": "The query is an aminocephalosporin sharing the alpha-amino-p-hydroxyphenylacetamido side chain with cefadroxil, amoxicillin, cephalexin, cefaclor, and cephradine; L5 records identify this beta-lactam class as PEPT1 substrates in the small intestine.",
      "card_ids": ["C206","C207","C208","C213","C182","C205","C199","C212","C220"]
    },
    {
      "claim": "Functional PEPT1 transport is shown for close analogs: cephalexin is absorbed rapidly in rat upper small intestine with pH-gradient dependent polarized Caco-2 transport and rat jejunum Papp of 4.52e-6 cm/s, and cefadroxil AUC falls when cephalexin competitively inhibits PEPT1 in humans.",
      "card_ids": ["C191","C184","C211","C194","C181","C197"]
    },
    {
      "claim": "L3 oral-exposure records show substantial systemic exposure for oral beta-lactams: cefadroxil Cmax about 16 µg/mL after 500 mg, cefaclor 8-17 µg/mL after 500 mg, and amoxicillin AUC 21.79 mg·h/L after 500 mg.",
      "card_ids": ["C85","C108","C95"]
    },
    {
      "claim": "L4 records show adequate solubility and measurable Caco-2 permeability for the class: amoxicillin solubility 3.4-7.69 mg/mL and Papp 0.69-1.8e-6 cm/s, and cefadroxil solubility 2.68 mg/mL.",
      "card_ids": ["C161","C162","C135","C146","C170","C143","C153","C151"]
    },
    {
      "claim": "L6 human data for orally absorbed cephalosporins show limited hepatic and biliary elimination: ceftibuten hepatic clearance was 23.8 ± 6.6 mL/min versus total 76.5 ± 9.4 mL/min, and cefixime biliary recovery was about 5% of dose; no record indicates high first-pass metabolism for the aminocephalosporin class.",
      "card_ids": ["C269","C241"]
    },
    {
      "claim": "Most L6 records concern non-oral or structurally distinct beta-lactams such as cefoperazone, ceftizoxime, cefotaxime, and flucloxacillin, so they do not transfer to the query and do not support F below 20%.",
      "card_ids": ["C249","C229","C256","C231"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C269","C241"]
    }
  ],
  "evidence_gaps": [
    "No cefatrizine-specific absolute oral bioavailability or matched oral-versus-IV AUC measurement is present.",
    "No cefatrizine-specific hepatic clearance or metabolic stability record is present; L6 evidence is analog-based.",
    "Most L6 hepatic-clearance records are for non-oral or structurally distinct beta-lactams and are not transferable.",
    "No query-specific PEPT1, efflux, or intestinal metabolism measurement is available.",
    "L1/L2 gold contexts are structurally unrelated to cephalosporins, limiting direct transferability."
  ],
  "decision_summary": "L6 adds no affirmative evidence of high first-pass hepatic loss for the query. Human hepatic-clearance data for orally absorbed cephalosporins (ceftibuten, cefixime) show limited hepatic and biliary elimination, which is supportive. Combined with L5 PEPT1-mediated uptake for the amino beta-lactam class and L3/L4 oral exposure, permeability, and solubility evidence, F >= 20% remains better supported. Prediction is high with moderate confidence."
}

